SELECT id,object_key,content_type,file_size,sku_id FROM bike_production_attachment WHERE sku_id=#{skuId}
AND id=#{imageId}
ORDER BY created_at,id LIMIT 1

SELECT COUNT(*) FROM bike_sales_order WHERE id=#{id} AND customer_id=#{customerId}
AND agent_id <=> #{agentId} AND status NOT IN ('CANCELLED','CLOSED')
FOR UPDATE

SELECT  FROM bike_pi_payment pay JOIN bike_pi p0 ON p0.id=pay.pi_id
JOIN bike_pi p1 ON (p1.series_id=p0.series_id OR (p1.series_id IS NULL AND p0.series_id IS NULL AND p1.id=p0.id))
WHERE p1.id=#{piId} AND pay.request_id=#{requestId}

