INSERT INTO bike_pi_item(pi_id,sku_id,product_model_id,sku_code,product_name,specification,model_name,ordered_qty,unit_price,discount_amount,tax_amount,line_total,unit,image_attachment_id,image_sha256)
SELECT #{targetPiId},sku_id,product_model_id,sku_code,product_name,specification,model_name,ordered_qty,unit_price,discount_amount,tax_amount,line_total,unit,image_attachment_id,image_sha256
FROM bike_pi_item WHERE pi_id=#{sourcePiId}
